    ClampVideoOption(&r, 3, 1, 2, 5);   bool ok = r == 3;            // explicit value wins
    ClampVideoOption(&r, -1, 4, 2, 5);  ok = ok && r == 2;           // fallback clamped to limit
    ClampVideoOption(&r, -1, 4, -1, 5); ok = ok && r == 4;           // under the secondary limit
